import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.D1JEzK2q.js";const u=JSON.parse('{"title":"WhatsApp Cloud API","description":"","frontmatter":{},"headers":[],"relativePath":"channels/whatsapp-cloud.md","filePath":"channels/whatsapp-cloud.md"}'),n={name:"channels/whatsapp-cloud.md"};function o(r,e,p,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="whatsapp-cloud-api" tabindex="-1">WhatsApp Cloud API <a class="header-anchor" href="#whatsapp-cloud-api" aria-label="Permalink to &quot;WhatsApp Cloud API&quot;">​</a></h1><p>This channel uses Meta&#39;s WhatsApp Business Cloud API with bearer-token requests and signed webhooks. The gateway integration handles direct messages. It is configured independently of the <a href="/claude-gateway/channels/whatsapp.html">WhatsApp linked-device bridge</a>.</p><h2 id="obtain-business-credentials" tabindex="-1">Obtain business credentials <a class="header-anchor" href="#obtain-business-credentials" aria-label="Permalink to &quot;Obtain business credentials&quot;">​</a></h2><p>You need a Meta developer account, business portfolio, WhatsApp Business Account (WABA), a business phone number or Meta test number, and a public HTTPS gateway URL.</p><ol><li>Create/configure a Meta app with the WhatsApp product/use case. Open its WhatsApp API setup panel.</li><li>For testing, select the test number and permitted recipient. Copy the access token and <strong>Phone Number ID</strong>.</li><li>For continued operation, create a system-user access token with access to the business assets and the required <code>whatsapp_business_messaging</code> / <code>whatsapp_business_management</code> permissions. A short-lived test token will expire.</li><li>Copy the app&#39;s <strong>App Secret</strong> from its settings. Generate your own random <strong>Verify Token</strong> for the webhook handshake; it is not the access token.</li></ol><p>Meta&#39;s <a href="https://www.postman.com/meta/whatsapp-business-platform/documentation/wlk6lh4/whatsapp-cloud-api" target="_blank" rel="noreferrer">official Cloud API collection</a> describes assets, tokens, permissions, phone-number registration and WABA subscription. Finish the number&#39;s registration and app/WABA subscription before testing inbound delivery.</p><h2 id="map-credentials-to-the-gateway" tabindex="-1">Map credentials to the gateway <a class="header-anchor" href="#map-credentials-to-the-gateway" aria-label="Permalink to &quot;Map credentials to the gateway&quot;">​</a></h2><p>Add this fragment to the existing agent configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;whatsapp_cloud&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;accessToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${WHATSAPP_CLOUD_ACCESS_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;phoneNumberId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${WHATSAPP_CLOUD_PHONE_NUMBER_ID}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;appSecret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${WHATSAPP_CLOUD_APP_SECRET}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;verifyToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${WHATSAPP_CLOUD_VERIFY_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dmAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sendReadReceipts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;reactionLevel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;templatesEnabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Supply these variables to the gateway environment and restart after a manual edit. <code>phoneNumberId</code> is Meta&#39;s ID for the sending number, not its digits, the WABA ID or App ID.</p><p>The agent PATCH API accepts <code>whatsapp_cloud_access_token</code>, <code>whatsapp_cloud_phone_number_id</code>, <code>whatsapp_cloud_app_secret</code> and <code>whatsapp_cloud_verify_token</code>. Send all four together when connecting/updating credentials. The CLI&#39;s four-platform connection wizard does not include this channel.</p><h2 id="configure-the-webhook" tabindex="-1">Configure the webhook <a class="header-anchor" href="#configure-the-webhook" aria-label="Permalink to &quot;Configure the webhook&quot;">​</a></h2><p>In Meta&#39;s WhatsApp/webhook settings, set the callback URL to your published gateway route:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gateway.example.com/gateway/webhooks/whatsapp_cloud/assistant</span></span></code></pre></div><p>Adjust the <code>/gateway</code> prefix for your proxy. Enter the same Verify Token as <code>verifyToken</code>, complete verification, and subscribe to <code>messages</code> notifications for the WABA/app. The handshake compares <code>hub.verify_token</code>; actual deliveries require <code>X-Hub-Signature-256</code>, computed from the exact raw request body using <code>appSecret</code>.</p><p>Keep the signature header and body intact through the proxy. A successful GET verification does not prove POST messages are delivered, so send a real message next.</p><h2 id="approve-the-first-sender" tabindex="-1">Approve the first sender <a class="header-anchor" href="#approve-the-first-sender" aria-label="Permalink to &quot;Approve the first sender&quot;">​</a></h2><p>Message the business number from a permitted test recipient or real customer account. In the gateway&#39;s WhatsApp Cloud settings, compare the pending sender&#39;s code and approve their number in <code>dmAllowlist</code>. Use international <strong>bare digits without <code>+</code></strong>, spaces or JID suffixes. Then send another message and verify a response.</p><p>For administrators, <code>GET /api/v1/agents/assistant/whatsapp_cloud/pending</code> lists denied senders. PATCH <code>whatsapp_cloud_dm_allowlist</code> on the agent to replace the allowlist, preserving existing entries. Policy fields are <code>whatsapp_cloud_dm_policy</code> and <code>whatsapp_cloud_pairing</code>. The Telegram/Discord <code>channels approve</code> CLI does not apply here.</p><p>There are no <code>groupPolicy</code>, <code>groupAllowlist</code> or <code>requireMention</code> fields for this integration.</p><h2 id="messages-and-templates" tabindex="-1">Messages and templates <a class="header-anchor" href="#messages-and-templates" aria-label="Permalink to &quot;Messages and templates&quot;">​</a></h2><p>The gateway normalizes text, images, supported documents, stickers, locations, contact data, and interactive button/list selections. Downloaded media is capped at 20 MB. Quoted-message context contains the referenced message ID; Meta does not include the original quoted text in this event. Audio/video ingestion and channel voice controls are not implemented here. Gateway <a href="/claude-gateway/guide/orchestration.html">orchestration</a> still applies to supported conversations.</p><p>Free-form replies depend on the 24-hour customer-service window following the user&#39;s latest message. Outside the window, use a Meta-approved message template. The gateway keeps <code>templatesEnabled: false</code> by default; explicitly enable it only when template sending is intended, then use an approved template name/language. Enabling the setting does not create or approve templates in Meta. Read receipts default on; <code>reactionLevel</code> is <code>ack</code> or <code>off</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Webhook verification fails</td><td>Matching Verify Token, HTTPS callback route and explicit agent ID</td></tr><tr><td>POST returns <code>401</code></td><td>Correct App Secret, signature present, raw bytes preserved</td></tr><tr><td>Verification passes but messages absent</td><td><code>messages</code> subscription, WABA/app subscription, correct business number</td></tr><tr><td>Outbound authentication fails</td><td>Expired test token, system-user asset assignment and token permissions</td></tr><tr><td>Sender never approved</td><td>Bare-digit allowlist format and pending entry for <code>whatsapp_cloud</code></td></tr><tr><td>Text reply refused outside service window</td><td>Approved template and <code>templatesEnabled</code>; inspect Meta&#39;s returned error</td></tr><tr><td>Templates still rejected</td><td>Exact approved template name/language and correct business account</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/whatsapp-cloud-webhook-router.ts" target="_blank" rel="noreferrer">Cloud webhook</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/whatsapp-cloud-client.ts" target="_blank" rel="noreferrer">Cloud client</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/whatsapp-cloud-access.ts" target="_blank" rel="noreferrer">access gate</a>.</p>`,26)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
